 public string ModelVersion{get;init;}=CurrentModelVersion; public string CalibrationVersion{get;init;}="petrophysics-calibration-default-v1";
 public double SampleSpacingM{get;init;}=2; public double VerticalResolutionM{get;init;}=4;
 public double SandMatrixDensityKgM3{get;init;}=2650; public double ShaleMatrixDensityKgM3{get;init;}=2720; public double GrSandApi{get;init;}=20; public double GrShaleApi{get;init;}=120;
