 public double OilHydrogenIndex{get;init;}=.9; public double WaterHydrogenIndex{get;init;}=1; public double GasHydrogenIndex{get;init;}=.15; public double ShaleNeutronResponse{get;init;}=.08;
 public double ArchieA{get;init;}=1; public double ArchieM{get;init;}=2; public double ArchieN{get;init;}=2; public double FormationWaterResistivityOhmM{get;init;}=.08;
 public double BoreholeDiameterM{get;init;}=.216; public double WashoutSensitivityM{get;init;}=.05;
 public double GrBiasApi{get;init;}=0; public double GrNoiseStdDevApi{get;init;}=1.5; public double GrDriftPer1000M{get;init;}=.5; public double GrClipMinApi{get;init;}=0; public double GrClipMaxApi{get;init;}=200;
 public double RhobBiasKgM3{get;init;}=0; public double RhobNoiseStdDevKgM3{get;init;}=8; public double RhobDriftPer1000M{get;init;}=3; public double RhobClipMinKgM3{get;init;}=800; public double RhobClipMaxKgM3{get;init;}=3200;
 public double NphiBiasFraction{get;init;}=0; public double NphiNoiseStdDevFraction{get;init;}=.008; public double NphiDriftPer1000M{get;init;}=.003; public double NphiClipMinFraction{get;init;}=-.15; public double NphiClipMaxFraction{get;init;}=.8;
 public double ResistivityBiasOhmM{get;init;}=0; public double ResistivityNoiseStdDevOhmM{get;init;}=.05; public double ResistivityDriftPer1000M{get;init;}=.02; public double ResistivityClipMinOhmM{get;init;}=.01; public double ResistivityClipMaxOhmM{get;init;}=10000;
 public double CaliperBiasM{get;init;}=0; public double CaliperNoiseStdDevM{get;init;}=.002; public double CaliperDriftPer1000M{get;init;}=0; public double CaliperClipMinM{get;init;}=.05; public double CaliperClipMaxM{get;init;}=.8;
 public double MissingProbability{get;init;}=.01; public int MissingIntervalMaxSamples{get;init;}=4; public double BadHoleProbability{get;init;}=.03;
 public double MdtSpacingM{get;init;}=100; public double MdtGaugeNoiseStdDevPa{get;init;}=15000; public double MdtGaugeUncertaintyPa{get;init;}=30000; public double MdtSuperchargePa{get;init;}=75000; public double MdtFailureProbability{get;init;}=.08; public double MdtSuperchargeProbability{get;init;}=.12;
 public int MaximumSamples{get;init;}=10000;
 public void Validate(){Token(ModelVersion);Token(CalibrationVersion);if(ModelVersion!=CurrentModelVersion)Fail("Unsupported log observation model version.");Between(SampleSpacingM,.1,500);Between(VerticalResolutionM,.1,1000);Between(SandMatrixDensityKgM3,1000,4000);Between(ShaleMatrixDensityKgM3,1000,4000);Between(GrSandApi,0,300);Between(GrShaleApi,0,300);if(GrSandApi>=GrShaleApi)Fail("GR endpoints must increase.");Between(OilDensityKgM3,50,2000);Between(WaterDensityKgM3,500,2000);Between(GasDensityKgM3,1,1000);Between(OilHydrogenIndex,0,1.5);Between(WaterHydrogenIndex,0,1.5);Between(GasHydrogenIndex,0,1.5);Between(ShaleNeutronResponse,0,1);Between(ArchieA,.1,10);Between(ArchieM,.5,5);Between(ArchieN,.5,5);Between(FormationWaterResistivityOhmM,.001,10);Between(BoreholeDiameterM,.05,1);Between(WashoutSensitivityM,0,.5);Between(MissingProbability,0,1);Between(BadHoleProbability,0,1);Between(MdtFailureProbability,0,1);Between(MdtSuperchargeProbability,0,1);if(MdtFailureProbability+MdtSuperchargeProbability>1)Fail("MDT probabilities exceed one.");Between(MdtSpacingM,1,1000);Between(MdtGaugeNoiseStdDevPa,0,1e7);Between(MdtGaugeUncertaintyPa,0,1e7);Between(MdtSuperchargePa,0,1e8);if(MissingIntervalMaxSamples<1||MissingIntervalMaxSamples>100||MaximumSamples<1||MaximumSamples>10000)Fail("Sample limits are invalid.");CheckCurve(GrClipMinApi,GrClipMaxApi,GrBiasApi,GrNoiseStdDevApi,GrDriftPer1000M);CheckCurve(RhobClipMinKgM3,RhobClipMaxKgM3,RhobBiasKgM3,RhobNoiseStdDevKgM3,RhobDriftPer1000M);CheckCurve(NphiClipMinFraction,NphiClipMaxFraction,NphiBiasFraction,NphiNoiseStdDevFraction,NphiDriftPer1000M);CheckCurve(ResistivityClipMinOhmM,ResistivityClipMaxOhmM,ResistivityBiasOhmM,ResistivityNoiseStdDevOhmM,ResistivityDriftPer1000M);CheckCurve(CaliperClipMinM,CaliperClipMaxM,CaliperBiasM,CaliperNoiseStdDevM,CaliperDriftPer1000M);}
 public string Hash(){Validate();return DeterministicIdentity.Sha256(CanonicalJson.Serialize(this));}
 private static void CheckCurve(double min,double max,double bias,double noise,double drift){double span=max-min,scale=Math.Max(Math.Abs(min),Math.Abs(max));if(!double.IsFinite(min)||!double.IsFinite(max)||min>=max||!double.IsFinite(bias)||Math.Abs(bias)>Math.Max(1,scale*2)||!double.IsFinite(noise)||noise<0||noise>span*2||!double.IsFinite(drift)||Math.Abs(drift)>span*2)Fail("Curve calibration is invalid.");}private static void Between(double x,double min,double max){if(!double.IsFinite(x)||x<min||x>max)Fail("Option outside validated bounds.");}private static void Token(string x){if(string.IsNullOrWhiteSpace(x)||x.Length>128||x.Any(c=>!(char.IsAsciiLetterOrDigit(c)||"-_.:".Contains(c))))Fail("Version token is invalid.");}private static void Fail(string m)=>throw new OptionsValidationException(nameof(LogObservationOptions),typeof(LogObservationOptions),[m]);
}
