public static class DeterministicLogObservationModel
{
 public static IReadOnlyList<LogCurveDefinition> CurveDefinitions(LogObservationOptions o)=>[new("GR","API",o.GrClipMinApi,o.GrClipMaxApi,o.GrNoiseStdDevApi),new("RHOB","kg/m3",o.RhobClipMinKgM3,o.RhobClipMaxKgM3,o.RhobNoiseStdDevKgM3),new("NPHI","fraction",o.NphiClipMinFraction,o.NphiClipMaxFraction,o.NphiNoiseStdDevFraction),new("RT_DEEP","ohm.m",o.ResistivityClipMinOhmM,o.ResistivityClipMaxOhmM,o.ResistivityNoiseStdDevOhmM),new("CALI","m",o.CaliperClipMinM,o.CaliperClipMaxM,o.CaliperNoiseStdDevM)];
 public static CleanPetrophysics ForwardClean(TruthSampleDto x,LogObservationOptions o){o.Validate();double shale=1-x.NetToGross,matrix=o.SandMatrixDensityKgM3*x.NetToGross+o.ShaleMatrixDensityKgM3*shale,fluid=o.OilDensityKgM3*x.OilSaturation+o.WaterDensityKgM3*x.WaterSaturation+o.GasDensityKgM3*x.GasSaturation;double gr=o.GrSandApi*x.NetToGross+o.GrShaleApi*shale,rhob=matrix*(1-x.Porosity)+fluid*x.Porosity,nphi=x.Porosity*(o.OilHydrogenIndex*x.OilSaturation+o.WaterHydrogenIndex*x.WaterSaturation+o.GasHydrogenIndex*x.GasSaturation)+shale*o.ShaleNeutronResponse;double sw=Math.Max(x.WaterSaturation,1e-6),phi=Math.Max(x.Porosity,1e-6),rt=o.ArchieA*o.FormationWaterResistivityOhmM/(Math.Pow(phi,o.ArchieM)*Math.Pow(sw,o.ArchieN));return new(gr,rhob,nphi,rt,o.BoreholeDiameterM);}
 public static (IReadOnlyList<LogObservationSample> Samples,IReadOnlyList<PressureObservation> Pressures,LogQcSummary Summary) Generate(string runId,IReadOnlyList<TruthSampleDto> truth,LogObservationOptions o){o.Validate();ValidateTruth(truth);double first=truth[0].MeasuredDepthM,last=truth[^1].MeasuredDepthM;int count=(int)Math.Floor((last-first)/o.SampleSpacingM)+1;if(last>first+(count-1)*o.SampleSpacingM+1e-9)count++;if(count<1||count>o.MaximumSamples)throw new RunStageFailureException("LogSampleLimitExceeded","Log series exceeds configured limit.");double[] md=Enumerable.Range(0,count).Select(i=>i==count-1?last:first+i*o.SampleSpacingM).ToArray();CleanPetrophysics[] raw=md.Select(x=>ForwardClean(Interpolate(truth,x),o)).ToArray(),smooth=new CleanPetrophysics[count];double radius=o.VerticalResolutionM/2;for(int i=0;i<count;i++){int[] window=Enumerable.Range(0,count).Where(j=>Math.Abs(md[j]-md[i])<=radius+1e-9).ToArray();smooth[i]=new(window.Average(j=>raw[j].GrApi),window.Average(j=>raw[j].RhobKgM3),window.Average(j=>raw[j].NphiFraction),window.Average(j=>raw[j].DeepResistivityOhmM),window.Average(j=>raw[j].CaliperM));}var rng=new HashRandom(runId+"\n"+o.Hash());var samples=new List<LogObservationSample>(count);int missing=0,badCount=0,missingRemaining=0;for(int i=0;i<count;i++){var q=new List<string>();bool bad=rng.Uniform()<o.BadHoleProbability;if(bad){q.Add("BadHole");badCount++;}if(missingRemaining==0&&rng.Uniform()<o.MissingProbability)missingRemaining=1+(int)(rng.Uniform()*o.MissingIntervalMaxSamples);bool miss=missingRemaining>0;if(miss){missingRemaining--;q.Add("MissingInterval");missing+=5;samples.Add(new(md[i],null,null,null,null,null,q));continue;}double drift=md[i]/1000;var x=smooth[i];double gr=Clip(x.GrApi+o.GrBiasApi+o.GrDriftPer1000M*drift+rng.Normal()*o.GrNoiseStdDevApi,o.GrClipMinApi,o.GrClipMaxApi,q,"GR");double rhob=Clip(x.RhobKgM3+o.RhobBiasKgM3+o.RhobDriftPer1000M*drift+rng.Normal()*o.RhobNoiseStdDevKgM3,o.RhobClipMinKgM3,o.RhobClipMaxKgM3,q,"RHOB");double nphi=Clip(x.NphiFraction+o.NphiBiasFraction+o.NphiDriftPer1000M*drift+rng.Normal()*o.NphiNoiseStdDevFraction,o.NphiClipMinFraction,o.NphiClipMaxFraction,q,"NPHI");double rt=Clip(x.DeepResistivityOhmM+o.ResistivityBiasOhmM+o.ResistivityDriftPer1000M*drift+rng.Normal()*o.ResistivityNoiseStdDevOhmM,o.ResistivityClipMinOhmM,o.ResistivityClipMaxOhmM,q,"RT_DEEP");double cal=x.CaliperM+o.CaliperBiasM+o.CaliperDriftPer1000M*drift+rng.Normal()*o.CaliperNoiseStdDevM+(bad?o.WashoutSensitivityM*(.5+rng.Uniform()):0);cal=Clip(cal,o.CaliperClipMinM,o.CaliperClipMaxM,q,"CALI");if(q.Count==0)q.Add("Valid");samples.Add(new(md[i],gr,rhob,nphi,rt,cal,q));}
 int pressureCapacity=(int)Math.Floor((last-first)/o.MdtSpacingM)+1;if(pressureCapacity>10000)throw new RunStageFailureException("PressureTestLimitExceeded","Pressure test series exceeds 10000 points.");var pressures=new List<PressureObservation>(pressureCapacity);int valid=0,failed=0,super=0;for(double x=first;x<=last+1e-9;x+=o.MdtSpacingM){double at=Math.Min(x,last),u=rng.Uniform();TruthSampleDto t=Interpolate(truth,at);if(u<o.MdtFailureProbability){pressures.Add(new(at,null,o.MdtGaugeUncertaintyPa,"Failed"));failed++;}else if(u<o.MdtFailureProbability+o.MdtSuperchargeProbability){pressures.Add(new(at,t.PressurePa+o.MdtSuperchargePa+rng.Normal()*o.MdtGaugeNoiseStdDevPa,o.MdtGaugeUncertaintyPa,"Supercharged"));super++;}else{pressures.Add(new(at,t.PressurePa+rng.Normal()*o.MdtGaugeNoiseStdDevPa,o.MdtGaugeUncertaintyPa,"Valid"));valid++;}if(at==last)break;}return(samples,pressures,new(missing,badCount,valid,failed,super));}
 private static double Clip(double x,double min,double max,List<string> q,string curve){double y=Math.Clamp(x,min,max);if(y!=x)q.Add(curve+"Clipped");return y;}private static void ValidateTruth(IReadOnlyList<TruthSampleDto> x){if(x.Count is<1 or>10000)throw new RunStageFailureException("TruthCoverageInvalid","Truth coverage is invalid.");double prior=-1;foreach(var t in x){if(t.MeasuredDepthM<=prior||!ReservoirSamplingClient.IsPhysicallyValid(t))throw new RunStageFailureException("TruthCoverageInvalid","Truth MD must increase.");prior=t.MeasuredDepthM;}}
 private static TruthSampleDto Interpolate(IReadOnlyList<TruthSampleDto> p,double md){int i=1;while(i<p.Count&&p[i].MeasuredDepthM<md)i++;if(i>=p.Count)return p[^1];var a=p[i-1];var b=p[i];double f=(md-a.MeasuredDepthM)/(b.MeasuredDepthM-a.MeasuredDepthM);return new(md,L(a.EastingM,b.EastingM),L(a.NorthingM,b.NorthingM),L(a.TrueVerticalDepthM,b.TrueVerticalDepthM),L(a.ReservoirTopDepthM,b.ReservoirTopDepthM),L(a.ReservoirBaseDepthM,b.ReservoirBaseDepthM),L(a.Porosity,b.Porosity),L(a.PermeabilityM2,b.PermeabilityM2),L(a.NetToGross,b.NetToGross),f<.5?a.IsReservoirQuality:b.IsReservoirQuality,L(a.PressurePa,b.PressurePa),L(a.OilSaturation,b.OilSaturation),L(a.WaterSaturation,b.WaterSaturation),L(a.GasSaturation,b.GasSaturation));double L(double x,double y)=>x+(y-x)*f;}
 private sealed class HashRandom(string seed){long n;public double Uniform(){byte[] h=SHA256.HashData(Encoding.UTF8.GetBytes(seed+"\n"+(n++).ToString(System.Globalization.CultureInfo.InvariantCulture)));return (BitConverter.ToUInt64(h,0)+1d)/(ulong.MaxValue+2d);}public double Normal(){double a=Uniform(),b=Uniform();return Math.Sqrt(-2*Math.Log(a))*Math.Cos(Math.Tau*b);}}
}






